PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?name WHERE {
  {
    SELECT ?s ?name (COUNT(DISTINCT ?tr) AS ?n) WHERE {
      ?tr a oncologia:Trial ; oncologia:status ?st ; oncologia:sponsor ?s ; oncologia:condition ?c .
      FILTER(?st IN ("TERMINATED", "WITHDRAWN"))
      ?s oncologia:industry true ; oncologia:name ?name .
      ?c oncologia:within ?m . ?m rdfs:label "Lung Neoplasms"@en .
    } GROUP BY ?s ?name
  }
} ORDER BY DESC(?n) LIMIT 3
